 private static void add(int p,String...ids){for(String id:ids)PAGES.put(id,p);}
 public static JSONArray ids(){JSONArray a=new JSONArray();for(String id:PAGES.keySet())a.put(id);return a;}
 public static JSONObject install(){int ok=0;JSONArray failed=new JSONArray();for(Map.Entry<String,Integer>e:PAGES.entrySet()){try{JSONObject r=new JSONObject().put("id",e.getKey()).put("domain",domain(e.getKey())).put("source_book",BOOK).put("source_locator","p."+e.getValue()).put("procedure_type","compiled_runtime_resolver").put("required_inputs",new JSONArray()).put("runtime_resolver","TashaSupplementalRuntimeEngine.resolve").put("auto_rolls",false);AuthorizedRuleProcedureEngine.register(r);ok++;}catch(Exception x){failed.put(e.getKey()+":"+x.getClass().getSimpleName());}}JSONObject o=new JSONObject();try{return o.put("installed",ok).put("expected",PAGES.size()).put("failed",failed).put("complete",ok==PAGES.size()).put("auto_rolls",false);}catch(Exception e){return o;}}
 public static JSONObject resolve(String id,JSONObject in){JSONObject x=in==null?new JSONObject():in,o=base(id);try{if(!PAGES.containsKey(id))return o.put("resolved",false).put("reason","unknown_tasha_supplemental_rule");o.put("resolved",true);JSONObject r;if(id.startsWith("tasha.artificer."))r=artificer(id,x,o);else if(id.startsWith("tasha.infusion."))r=infusion(id,x,o);else if(id.startsWith("tasha.invocation."))r=invocation(id,x,o);else if(id.startsWith("tasha.maneuver."))r=maneuver(id,x,o);else if(id.startsWith("tasha.style."))r=style(id,x,o);else r=classFeature(id,x,o);if(r!=o&&!r.has("rule_id")){o.put("effect",r);return o;}return r;}catch(Exception e){try{return o.put("resolved",false).put("error",e.getClass().getSimpleName());}catch(Exception ignored){return o;}}}
